import exercises from'./data/exercises.js';import anatomy from'./data/anatomy.js';import{store}from'./storage/store.js';import{exById,sessionMetrics,bodyState,muscleSummary,streak,weekly,recs,allSets}from'./analytics/engine.js';import{bodyMap}from'./components/bodyMap.js';import{chart}from'./components/chart.js';import{esc,nav,header,toast}from'./components/ui.js';
const A=document.querySelector('#app'),parts=['Chest','Triceps','Back','Biceps','Legs','Shoulders','Abs','Forearms'];let install=null;addEventListener('beforeinstallprompt',e=>{e.preventDefault();install=e;showInstallBtn()});addEventListener('appinstalled',()=>{install=null;hideInstallBtn()});function showInstallBtn(){let b=document.querySelector('#pwa-install');if(b)return;b=document.createElement('button');b.id='pwa-install';b.className='pwa-install';b.type='button';b.setAttribute('aria-label','Install PROGRESS app');b.innerHTML=`<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v12"/><path d="m7 10 5 5 5-5"/><path d="M5 21h14"/></svg><span>Install</span>`;b.onclick=async()=>{if(!install)return;install.prompt();let r=await install.userChoice;if(r&&r.outcome==='accepted'){install=null;hideInstallBtn()}};document.body.append(b);requestAnimationFrame(()=>b.classList.add('show'))}function hideInstallBtn(){let b=document.querySelector('#pwa-install');if(!b)return;b.classList.remove('show');setTimeout(()=>b.remove(),250)}if(window.matchMedia&&window.matchMedia('(display-mode: standalone)').matches)hideInstallBtn();if('serviceWorker'in navigator)addEventListener('load',()=>{navigator.serviceWorker.register(new URL('sw.js',document.baseURI),{scope:new URL('./',document.baseURI).pathname}).catch(()=>{})});const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`},date=x=>new Date(x+'T12:00:00').toLocaleDateString('en',{month:'short',day:'numeric',year:'numeric'});
function render(){let r=location.hash.slice(2)||'dashboard';if(!store.get().onboarded&&r!=='onboarding'){location.hash='#/onboarding';return}({onboarding,dashboard,log,progress,analytics,profile,settings}[r]||dashboard)();}function shell(html,a){A.innerHTML=`<main>${html}</main>${nav(a)}`;}
function onboarding(){A.innerHTML=`<div class="onboard"><div class="hero"><img src="./hero.png"><div class="shade"></div><strong>PROGRESS</strong><div class="hero-copy"><span>TRAIN. TRACK. IMPROVE.</span><h1>Keep the record<br>of <em>every lift.</em></h1><p>Track. Analyze. Improve.</p><button class="hero-start" id="hero-start">Get Started →</button></div></div><section class="setup"><span class="eyebrow">WELCOME TO PROGRESS</span><h2>Your training, organized.</h2><p>No account. No cloud. Your data stays on this device.</p><form id="setup"><label>Name<input name="name" required placeholder="Your name"></label><div class="two"><label>Age<input name="age" type="number" min="13" max="100"></label><label>Height<input name="height" type="number" placeholder="175"><i>cm</i></label></div><label>Current weight<input name="weight" type="number" step="0.1" placeholder="72.5"><i>kg</i></label><div class="two"><label>Goal<select name="goal"><option>Muscle Gain</option><option>Strength</option><option>General Fitness</option><option>Fat Loss</option></select></label><label>Experience<select name="experience"><option>Beginner</option><option selected>Intermediate</option><option>Advanced</option></select></label></div><button class="primary">Start with PROGRESS →</button></form></section></div>`;document.querySelector('#hero-start')?.addEventListener('click',()=>{document.querySelector('.setup')?.scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('#setup input[name=name]')?.focus()});document.querySelector('#setup').onsubmit=e=>{e.preventDefault();let f=new FormData(e.currentTarget);store.completeOnboarding({name:f.get('name'),age:+f.get('age')||null,height:+f.get('height')||null,weight:+f.get('weight')||null,goal:f.get('goal'),experience:f.get('experience')});location.hash='#/dashboard'}}
function dashboard(){let s=store.get(),st=streak(s),w=weekly(s),last=s.workouts[0],lb=s.settings.lastBackup,needsBackup=!lb||(Date.now()-new Date(lb).getTime())>7*24*60*60*1000,totalSets=s.workouts.reduce((n,w)=>n+w.exercises.reduce((a,x)=>a+x.sets.length,0),0);shell(`<div class="page"><div class="dash-head"><button class="ghost">☰</button><b>PROGRESS</b><button class="ghost">♧</button></div><p class="muted">Good morning, ${esc(s.profile.name)} 👋</p><h2 class="big">Let's crush your<br>goals today.</h2><section class="card streak"><div><span class="label">CURRENT STREAK</span><strong>⌁ ${st.current}<small> days</small></strong></div><span class="muted">Best: ${st.best} days</span><div class="dots">${w.map(x=>`<span><b class="${x.count?'on':''}">${x.count?'✓':''}</b><small>${x.day}</small></span>`).join('')}</div></section>${last?`<section class="card last"><div><span class="label">LAST WORKOUT</span><h3>${esc(exById[last.exercises[0].exerciseId]?.name||'Workout')}</h3><p>${date(last.date)} · ${last.exercises.length} exercise${last.exercises.length>1?'s':''}</p></div><span class="mini">✦</span></section>`:''}<a class="button primary" href="#/log">＋ Log Your Exercise</a>${s.workouts.length?`<section class="card backup ${needsBackup?'warn':''}"><div><span class="label">BACKUP</span><h3>${lb?`Last backup ${date(lb.slice(0,10))}`:'No backup yet'}</h3><p>${totalSets} sets logged · stored on this device</p></div><button class="button secondary sm" id="quickbackup">↓ ${lb?'Export':'Save backup'}</button></section>`:''}<div class="quick"><a class="card" href="#/progress">↗ <b>View Progress</b></a><a class="card" href="#/analytics">◒ <b>View Analytics</b></a></div><section class="card weekly"><div class="between"><span><span class="label">WEEKLY OVERVIEW</span><b>${s.workouts.reduce((n,x)=>n+x.exercises.length,0)} exercises</b></span><strong>${w.filter(x=>x.count).length}<small> of 7 days</small></strong></div><div class="bars">${w.map(x=>`<span><i style="height:${Math.max(10,x.count*28)}px"></i><small>${x.day}</small></span>`).join('')}</div></section></div>`,'dashboard');document.querySelector('#quickbackup')?.addEventListener('click',()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([store.export()],{type:'application/json'}));a.download=`progress-backup-${today()}.json`;a.click();store.markBackup();toast('Backup saved');render()})}
function log(){shell(`${header('Log Your Exercise')}<div class="page"><span class="eyebrow">1 / BODY PART</span><h2>Start with the muscle.</h2><p class="muted">Choose a body part first. Only its supported exercises appear.</p><div class="chips">${parts.map((p,i)=>`<button class="chip ${i?'':'sel'}" data-part="${p}">${p}</button>`).join('')}</div><span class="eyebrow">2 / EXERCISE</span><h3 id="count"></h3><div id="elist"></div><div id="logform"></div></div>`,'log');let part='Chest',selected=null;const draw=()=>{let rows=exercises.filter(e=>e.bodyPart===part);document.querySelector('#count').textContent=`${part} · ${rows.length} exercises`;document.querySelector('#elist').innerHTML=`<div class="exdd" id="exdd"><button type="button" class="exdd-trigger ${selected?'has':''}" id="exdd-trigger"><span class="exdd-value">${selected?(()=>{let s=exById[selected];return`<span class="exicon">${s.equipment==='Cable'?'◌':s.equipment==='Machine'?'▣':s.equipment==='Dumbbell'?'◒':'▤'}</span><span class="exdd-text"><b>${esc(s.name)}</b><small>${esc(s.equipment)}</small></span>`})():`<span class="exdd-placeholder"><span class="exicon">⌕</span><span class="exdd-text"><b>Select an exercise</b><small>·  Tap to choose</small></span></span>`}</span><span class="exdd-caret">▾</span></button><div class="exdd-panel" id="exdd-panel"><div class="exdd-search">⌕<input id="q" placeholder="Search exercise..."></div><div class="exdd-list">${rows.map(e=>`<button type="button" class="exdd-item ${selected===e.id?'selected':''}" data-ex="${e.id}"><span class="exicon">${e.equipment==='Cable'?'◌':e.equipment==='Machine'?'▣':e.equipment==='Dumbbell'?'◒':'▤'}</span><span class="exdd-text"><b>${esc(e.name)}</b><small>${esc(e.equipment)}</small></span><span class="exdd-tick">✓</span></button>`).join('')}</div></div></div>`;initDD()};function initDD(){let trigger=document.querySelector('#exdd-trigger'),dd=document.querySelector('#exdd');trigger.onclick=e=>{e.stopPropagation();dd.classList.toggle('open');if(dd.classList.contains('open'))setTimeout(()=>document.querySelector('#q')?.focus(),50)};document.querySelector('#q').oninput=e=>{let v=e.target.value.toLowerCase();document.querySelectorAll('.exdd-item').forEach(it=>{let ex=exById[it.dataset.ex];it.style.display=ex&&ex.name.toLowerCase().includes(v)?'':'none'})};document.querySelectorAll('.exdd-item').forEach(it=>it.onclick=e=>{e.stopPropagation();selected=it.dataset.ex;dd.classList.remove('open');draw();form(selected)})}draw();document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{part=b.dataset.part;selected=null;document.querySelectorAll('[data-part]').forEach(x=>x.classList.toggle('sel',x===b));document.querySelector('#logform').innerHTML='';draw()});addEventListener('click',e=>{let dd=document.querySelector('.exdd');if(dd&&dd.classList.contains('open')&&!dd.contains(e.target))dd.classList.remove('open')});function form(id){let ex=exById[id];document.querySelector('#logform').innerHTML=`<hr><span class="eyebrow">3 / LOG SETS</span><h3>${ex.name}</h3><label>Body Weight <small>optional</small><div class="field"><input id="bw" type="number" step="0.1" value="${store.get().profile.weight||''}"><span>kg</span></div></label><div class="sets"><div class="sethead"><span>Set</span><span>Reps</span><span>Weight</span><span></span></div><div id="rows">${row(1)}${row(2)}${row(3)}</div><button id="add" class="add">＋ Add Another Set</button></div><button id="save" class="button primary full">Save Exercise</button>`;document.querySelector('#add').onclick=()=>{let n=document.querySelectorAll('.srow').length+1;document.querySelector('#rows').insertAdjacentHTML('beforeend',row(n));bindDel()};document.querySelector('#save').onclick=()=>{let sets=[...document.querySelectorAll('.srow')].map(r=>({reps:r.querySelector('.reps').value,weight:r.querySelector('.weight').value})).filter(x=>+x.reps>0&&+x.weight>=0);if(!sets.length)return toast('Add a valid set');store.addExercise({date:today(),bodyWeight:document.querySelector('#bw').value,exerciseId:id,sets});toast('Exercise saved');location.hash='#/progress'};bindDel()}function row(n){return`<div class="srow"><b>${n}</b><input class="reps" type="number" placeholder="10"><input class="weight" type="number" step="0.5" placeholder="80"><button class="del">×</button></div>`}function bindDel(){document.querySelectorAll('.del').forEach(b=>b.onclick=()=>{if(document.querySelectorAll('.srow').length>1)b.parentElement.remove()})}}
function progress(){shell(`${header('Progress')}<div class="page"><label>Select Exercise<div class="field"><select id="pex">${exercises.map(e=>`<option value="${e.id}">${e.name}</option>`).join('')}</select></div></label><div class="seg"><button data-range="30" class="sel">1M</button><button data-range="90">3M</button><button data-range="180">6M</button><button data-range="365">1Y</button><button data-range="all">All</button></div><div class="seg"><button data-metric="volume" class="sel">Volume</button><button data-metric="maxWeight">Max Weight</button><button data-metric="bestE1rm">e1RM</button></div><section class="card chartbox"><span class="label" id="mlabel">MAX WEIGHT</span><h2 id="mvalue">—</h2><div id="chart"></div></section><div class="statgrid" id="stats"></div><button class="button secondary full" id="sets">View Sets</button></div>`,'progress');let metric='volume',days=90,sel=document.querySelector('#pex');const draw=()=>{let a=sessionMetrics(store.get(),sel.value);if(days!=='all'){let c=new Date();c.setDate(c.getDate()-days);a=a.filter(x=>new Date(x.date+'T12:00:00')>=c)}chart(document.querySelector('#chart'),a,metric);let z=a.at(-1),label=metric==='maxWeight'?'MAX WEIGHT':metric==='volume'?'TOTAL VOLUME':'EST. 1RM';document.querySelector('#mlabel').textContent=label;document.querySelector('#mvalue').textContent=z?`${metric==='volume'?Math.round(z[metric]).toLocaleString():z[metric].toFixed(1)} kg`:'—';let all=sessionMetrics(store.get(),sel.value);document.querySelector('#stats').innerHTML=`<div><b>${all.length?Math.max(...all.map(x=>x.maxWeight)).toFixed(1):'—'} kg</b><small>Current Max</small></div><div><b>${all.length?Math.round(Math.max(...all.map(x=>x.volume))).toLocaleString():'—'} kg</b><small>Best Volume</small></div><div><b>${all.length}</b><small>Workouts</small></div>`};sel.onchange=draw;document.querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>{metric=b.dataset.metric;document.querySelectorAll('[data-metric]').forEach(x=>x.classList.toggle('sel',x===b));draw()});document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{days=b.dataset.range==='all'?'all':+b.dataset.range;document.querySelectorAll('[data-range]').forEach(x=>x.classList.toggle('sel',x===b));draw()});document.querySelector('#sets').onclick=()=>{let a=allSets(store.get()).filter(x=>x.exerciseId===sel.value);let html=a.length?a.sort((x,y)=>y.date.localeCompare(x.date)).map(x=>`<div class="history"><b>${date(x.date)}</b><span>Set ${x.set}</span><strong>${x.weight} kg × ${x.reps}</strong><em>${x.volume.toLocaleString()} kg</em></div>`).join(''):'<div class="empty">No sets logged.</div>';modal('Set History',html)};draw()}
function analytics(){shell(`${header('Analytics')}<div class="page"><div class="seg"><button class="sel" data-period="week">This Week</button><button data-period="month">This Month</button></div><div class="tabs"><button class="sel" data-tab="map">Muscle Map</button><button data-tab="stats">Muscle Stats</button></div><div id="ac"></div></div>`,'analytics');let period='week',tab='map',map=null;const draw=()=>{let c=document.querySelector('#ac');if(tab==='stats'){c.innerHTML=`<section class="card statslist">${muscleSummary(store.get(),period).map(x=>`<div><span>${x.name}</span><i><b style="width:${x.score*10}%"></b></i><strong>${x.score}/10</strong></div>`).join('')||'<div class="empty">Log a workout to see muscle statistics.</div>'}</section>`;return}c.innerHTML=`<div class="mapbar"><div class="seg mini"><button class="sel" data-view="FRONT">Front</button><button data-view="BACK">Back</button></div><small>Muscle load · ${period==='week'?'current week':'weekly average'}</small></div><section class="card body"><div id="bm"></div><div class="legend">Low <i></i> High</div></section><div class="recs"><span class="eyebrow">RECOMMENDATIONS</span>${recs(store.get()).map(x=>`<div class="rec"><b>✦</b><span><strong>${x.title}</strong><small>${x.text}</small></span>›</div>`).join('')}</div>`;map=bodyMap(document.querySelector('#bm'),bodyState(store.get(),period));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('sel',x===b));map.view(b.dataset.view)});};document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=b.dataset.period;document.querySelectorAll('[data-period]').forEach(x=>x.classList.toggle('sel',x===b));draw()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('sel',x===b));draw()});draw()}
function profile(){let p=store.get().profile,st=streak(store.get()),n=store.get().workouts.reduce((a,w)=>a+w.exercises.length,0);shell(`${header('Profile')}<div class="page profile"><div class="avatar">${esc((p.name||'P')[0])}</div><h2>${esc(p.name||'Your Name')}</h2><p class="muted">${p.goal}</p><div class="statstrip"><b>${n}<small>Exercises</small></b><b>${st.current}<small>Streak</small></b><b>${store.get().workouts.length}<small>Workouts</small></b></div><div class="list"><button data-edit>Personal Information <span>›</span></button><button data-edit>Fitness Goal <span>${p.goal}</span></button><button data-edit>Training Experience <span>${p.experience}</span></button><button data-edit>Body Weight <span>${p.weight||'—'} kg</span></button><button data-edit>Height <span>${p.height||'—'} cm</span></button></div><a class="button secondary full" href="#/settings">Settings</a></div>`,'profile');document.querySelectorAll('[data-edit]').forEach(x=>x.onclick=edit)}
function edit(){let p=store.get().profile;modal('Edit Profile',`<form id="pf"><label>Name<input name="name" value="${esc(p.name)}"></label><div class="two"><label>Age<input name="age" value="${p.age||''}"></label><label>Height<input name="height" value="${p.height||''}"></label></div><label>Weight<input name="weight" value="${p.weight||''}"></label><label>Goal<select name="goal">${['Muscle Gain','Strength','General Fitness','Fat Loss'].map(x=>`<option ${x===p.goal?'selected':''}>${x}</option>`).join('')}</select></label><button class="button primary full">Save</button></form>`);document.querySelector('#pf').onsubmit=e=>{e.preventDefault();let f=new FormData(e.currentTarget);store.updateProfile({name:f.get('name'),age:+f.get('age')||null,height:+f.get('height')||null,weight:+f.get('weight')||null,goal:f.get('goal')});document.querySelector('.modalbg').remove();render()}}
function settings(){shell(`${header('Settings')}<div class="page settings"><span class="eyebrow">PREFERENCES</span><div class="list"><button>Units <select id="units"><option>kg</option><option>lb</option></select></button><button id="install">Install PROGRESS <span>›</span></button></div><span class="eyebrow">DATA & PRIVACY</span><div class="list"><button id="export">Export Data <span>↓</span></button><button id="import">Import Data <span>↑</span></button><button>Storage <span>Local only</span></button></div><span class="eyebrow">SUPPORT</span><div class="list"><button>Help & FAQ <span>›</span></button><button>About PROGRESS <span>v1.0</span></button></div><button class="button danger full" id="clear">Clear all local data</button></div>`,'profile');document.querySelector('#install').onclick=async()=>{if(install){install.prompt();await install.userChoice;install=null}};document.querySelector('#units').value=store.get().settings.unit;document.querySelector('#units').onchange=e=>store.updateSettings({unit:e.target.value});document.querySelector('#export').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([store.export()],{type:'application/json'}));a.download=`progress-backup-${today()}.json`;a.click();store.markBackup();toast('Backup saved')};document.querySelector('#import').onclick=()=>{let i=document.createElement('input');i.type='file';i.accept='.json';i.onchange=async()=>{try{store.import(await i.files[0].text());render();toast('Backup imported')}catch{toast('Invalid backup')}};i.click()};document.querySelector('#clear').onclick=()=>{if(confirm('Clear all local data?')){store.reset();location.hash='#/onboarding'}}}
function modal(t,b){let x=document.createElement('div');x.className='modalbg';x.innerHTML=`<div class="modal"><div class="modalhead"><h3>${t}</h3><button data-close>×</button></div><div class="modalbody">${b}</div></div>`;document.body.append(x);x.onclick=e=>{if(e.target===x||e.target.closest('[data-close]'))x.remove()};return x}
window.__storeError=msg=>toast(msg);
addEventListener('hashchange',render);render();
